import React from "react";
import '../css/login.css';
import { Link, useNavigate } from "react-router-dom";

class Welcome extends React.Component {
    render() {
        return (
            <>
                {/* عکس ثابت در گوشه بالا‑چپ */}
                <img 
                    src="../img/logo.png"   // مسیر عکس خود را وارد کنید
                    alt="logo"
                    className="fixed-top-left"
                />

                <main className="vh-100 d-flex align-items-center justify-content-center">
                    <div className="container-fluid">
                        <div className="row">
                            <div className="col-12 d-flex justify-content-center">
                                <div className="login-box-login shadow text-center item-back border p-4 rounded-5">
                                    <img src="../img/aaa.png" alt="welcome" />
                                    <div className="mt-5">
                                        <p>
                                            <b>سرویسی امن و راحت برای خدمت رسانی به مشتریان</b>
                                        </p>
                                        <div className="mx-4 mt-4">
                                            <a className="btn btn-primary w-100 rounded-4">شروع</a>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </main>
            </>
        );
    }
}

export default Welcome;
